flow.set("NightDischargePower", 0);
flow.set("PowerL1SetPoint", 0);
node.status({fill:"blue", shape:"ring", text:"Nachtentladung gestartet"});
msg.payload = 3;
return msg;

// === Nachtentladung 00:00 - 07:00 auf SOC_TARGET, kein Netzbezug ===
const CAPACITY_WH = 16000; // Akku-Nutzkapazitaet in Wh
const P_MAX       = 3800;  // max. Entladeleistung Wechselrichter (W)
const SOC_TARGET  = 10;    // Ziel-SoC (%)
const GRID_TARGET = 0;     // Ziel-Netzleistung (W); 0 = kein Bezug

const now = new Date();
const minutes = now.getHours() * 60 + now.getMinutes();
const inWindow = (minutes >= 0 && minutes < 7 * 60);

// Ausserhalb 00:00-07:00 nichts tun (Stop uebernimmt der 07:00-Inject)
if (!inWindow) {
    node.status({});
    return [null, null];
}

const soc  = Number(flow.get("ESS_SoC"));
const grid = Number(flow.get("GridPower")) || 0;   // + = Netzbezug
let   cur  = Number(flow.get("NightDischargePower")) || 0;

// Ziel erreicht -> Entladung stoppen, ESS zurueck auf Optimized (1)
if (!isNaN(soc) && soc <= SOC_TARGET) {
    flow.set("NightDischargePower", 0);
    flow.set("PowerL1SetPoint", 0);
    node.status({fill:"green", shape:"dot", text:"Ziel " + SOC_TARGET + "% erreicht"});
    return [ {payload: 0}, {payload: 1} ];
}

// 1) geplante Entladeleistung, um bis 07:00 auf SOC_TARGET zu kommen
const hoursLeft = Math.max((7 * 60 - minutes) / 60, 0.1);
const energyWh  = Math.max(((isNaN(soc) ? 100 : soc) - SOC_TARGET) / 100 * CAPACITY_WH, 0);
const planned   = energyWh / hoursLeft;

// 2) Hauslast-Deckung: aktuelle Last ~ aktuelle Entladung + Netzbezug
//    Entladung mind. so gross wie Last -> kein Netzbezug
const coverLoad = cur + (grid - GRID_TARGET);

// Groesserer der beiden Werte, auf Wechselrichtergrenze begrenzt
let mag = Math.max(planned, coverLoad, 0);
mag = Math.min(mag, P_MAX);

flow.set("NightDischargePower", mag);
flow.set("PowerL1SetPoint", mag); // haelt 2s-Apply-Loop konsistent (HA pausiert)

node.status({fill:"blue", shape:"dot",
    text:"SoC " + soc + "% | Soll " + Math.round(mag) + "W | Netz " + Math.round(grid) + "W"});

// Ausgang 1: AcPowerSetpoint (negativ = entladen)
// Ausgang 2: ESS-Mode 3 (External control) erneut bestaetigen
return [ {payload: -Math.round(mag)}, {payload: 3} ];

// Entladung beenden: Sollwert 0, ESS zurueck auf Optimized (1)
flow.set("NightDischargePower", 0);
flow.set("PowerL1SetPoint", 0);
node.status({fill:"grey", shape:"ring", text:"Nachtentladung beendet"});
// Ausgang 1: AcPowerSetpoint = 0 ; Ausgang 2: ESS-Mode 1
return [ {payload: 0}, {payload: 1} ];
